      await onConfirm({
        name,
        classId: classes[classIndex].id,
        seed: seedVal,
        difficulty,
        tutorial,
        disableGore,
        onProgress: generationPanel.progress,
      });
      generationPanel.complete();
      generationPanel.dispose();
      dispose({ fade: true });
    });
  }

