// display/camera/controller.js
// Core camera resource (pure data + helpers)

export function createCamera() {
  return {
    x: 0,
    y: 0,
    scale: 1,
    targetX: 0,
    targetY: 0,
    targetScale: 1,
    lerpSpeed: 4.0,
    shakeX: 0,
    shakeY: 0
  };
}

function smoothStep(t) {
  const u = Math.max(0, Math.min(1, t));
  return u * u * (3 - 2 * u);
